"use client";

import { cn } from "@/lib/utils";
import {
  CanvasStage,
  ImageFallback,
} from "@/registry/ivan/components/canvas-stage/canvas-stage";
import { centeredFocus } from "@/registry/ivan/lib/image-cover";

import { stormPrintDefaults } from "./storm-print-material";
import { StormPrintScene } from "./storm-print-scene";
import type { StormPrintSceneProps } from "./storm-print-scene";

export interface StormPrintProps extends StormPrintSceneProps {
  className?: string;
  label?: string;
}

const defaultLabel =
  "A picture printed as an ordered dither, reprinted in color by lightning strikes and clicks";

export const StormPrint = ({
  className,
  label = defaultLabel,
  src,
  focus = centeredFocus,
  ink = stormPrintDefaults.ink,
  paper = stormPrintDefaults.paper,
  paused = stormPrintDefaults.paused,
  ...sceneProps
}: StormPrintProps) => (
  <CanvasStage
    className={cn("touch-pan-y", className)}
    fallback={<ImageFallback focus={focus} src={src} />}
    ground={ink}
    label={label}
    paused={paused}
  >
    {(isAnimating) => (
      <StormPrintScene
        {...sceneProps}
        focus={focus}
        ink={ink}
        paper={paper}
        paused={!isAnimating}
        src={src}
      />
    )}
  </CanvasStage>
);

"use client";

import { useFrame, useThree } from "@react-three/fiber";
import { useEffect, useMemo, useRef } from "react";
import { MathUtils, PlaneGeometry, Vector3 } from "three";
import type { Intersection, Mesh, Raycaster, WebGLRenderer } from "three";

import { usePrintImage } from "@/registry/ivan/hooks/use-print-image";
import type { PrintImage } from "@/registry/ivan/hooks/use-print-image";
import { createBlueNoiseTexture } from "@/registry/ivan/lib/blue-noise";
import {
  centeredFocus,
  readViewport,
  setCoverImage,
} from "@/registry/ivan/lib/image-cover";
import type { ImageFocus } from "@/registry/ivan/lib/image-cover";
import { samplePalette } from "@/registry/ivan/lib/palette";
import type { Rgb } from "@/registry/ivan/lib/palette";
import { PointerTrace } from "@/registry/ivan/lib/pointer-trace";
import type { PointerSample } from "@/registry/ivan/lib/pointer-trace";
import {
  createSpring,
  driveSpring,
  frameStep,
} from "@/registry/ivan/lib/spring";

import {
  StormPrintMaterial,
  stormDitherIndex,
  stormPrintDefaults,
} from "./storm-print-material";
import type { StormDither } from "./storm-print-material";
import { advanceStorm, createStorm } from "./storm-timeline";
import type { StrikePoint } from "./storm-timeline";

export type StormPrintMode = "ink" | "color";

export interface StormPrintSceneProps {
  src: string;
  focus?: ImageFocus;
  ink?: string;
  paper?: string;
  dither?: StormDither;
  print?: StormPrintMode;
  cell?: number;
  threshold?: number;
  contrast?: number;
  rain?: number;
  rainSpeed?: number;
  rainAngle?: number;
  lightning?: boolean;
  frequency?: number;
  flash?: number;
  colorHold?: number;
  aura?: number;
  auraRadius?: number;
  strikes?: number;
  paused?: boolean;
}

interface StormLook {
  ink: string;
  paper: string;
  dither: StormDither;
  print: StormPrintMode;
  cell: number;
  threshold: number;
  contrast: number;
  rain: number;
  rainSpeed: number;
  rainAngle: number;
  lightning: boolean;
  frequency: number;
  flash: number;
  colorHold: number;
  aura: number;
  auraRadius: number;
}

interface StormFrame {
  delta: number;
  paused: boolean;
  pointer: PointerSample;
}

const followSpring = { damping: 18, stiffness: 140 } as const;
const auraSpring = { damping: 12, stiffness: 90 } as const;
const burstKick = 6;
const rainRate = 4;
const shakeLength = 0.24;
const shakeCells = 2;
const auraSize = 0.22;

const hitEverywhere = function hitEverywhere(
  this: Mesh,
  _raycaster: Raycaster,
  intersects: Intersection[]
) {
  intersects.push({ distance: 0, object: this, point: new Vector3() });
};

class StormPrintRig {
  readonly material = new StormPrintMaterial();
  readonly geometry = new PlaneGeometry(1, 1);
  private readonly blueNoise = createBlueNoiseTexture();
  private readonly trace = new PointerTrace();
  private readonly storm = createStorm();
  private readonly aura = {
    strength: createSpring(0),
    x: createSpring(0.62),
    y: createSpring(0.6),
  };
  private readonly burst = { age: Infinity, x: 0.5, y: 0.5 };
  private look: StormLook | null = null;
  private pendingPress: StrikePoint | null = null;
  private isStrikeRequested = false;
  private rain: number = stormPrintDefaults.rain;
  private shakeX = 0;
  private shakeY = 0;

  constructor() {
    this.material.uniforms.uBlueNoise.value = this.blueNoise;
  }

  applyLook(look: StormLook) {
    const { uniforms } = this.material;
    this.look = look;
    uniforms.uInk.value.set(look.ink);
    uniforms.uPaper.value.set(look.paper);
    uniforms.uDither.value = stormDitherIndex(look.dither);
    uniforms.uThreshold.value = look.threshold;
    uniforms.uContrast.value = look.contrast;
    uniforms.uRainSpeed.value = look.rainSpeed;
    uniforms.uRainSlant.value = Math.tan(MathUtils.degToRad(look.rainAngle));
    uniforms.uAuraSize.value = auraSize * look.auraRadius;
  }

  applyImage(image: PrintImage | null, focus: ImageFocus) {
    setCoverImage(this.material.uniforms, image, focus);
  }

  applyPalette(palette: readonly Rgb[]) {
    const inks = this.material.uniforms.uPalette.value;
    for (const [index, [red, green, blue]] of palette.entries()) {
      inks[index]?.set(red / 255, green / 255, blue / 255);
    }
  }

  strike() {
    this.isStrikeRequested = true;
  }

  press(x: number, y: number) {
    this.pendingPress = { x, y };
    this.isStrikeRequested = true;
  }

  advance({ delta, paused, pointer }: StormFrame) {
    const { look } = this;
    if (!look) {
      return;
    }
    const { aura, burst, storm, trace } = this;
    const { uniforms } = this.material;
    const step = frameStep(delta);
    const isMoving = !paused;
    trace.update(pointer, step, isMoving);

    advanceStorm(
      storm,
      {
        colorHold: look.colorHold,
        flash: look.flash,
        frequency: look.frequency,
        lightning: look.lightning,
      },
      {
        isRequested: this.isStrikeRequested,
        landing: this.pendingPress,
        mode: isMoving ? "running" : "still",
        random: Math.random,
        step,
      }
    );
    this.isStrikeRequested = false;

    this.rain = isMoving
      ? this.rain + (look.rain - this.rain) * (1 - Math.exp(-step * rainRate))
      : look.rain;

    if (this.pendingPress && isMoving) {
      burst.age = 0;
      burst.x = this.pendingPress.x;
      burst.y = this.pendingPress.y;
      aura.strength.velocity += burstKick;
    }
    this.pendingPress = null;
    if (isMoving) {
      burst.age += step;
    } else {
      burst.age = Infinity;
    }

    const shake =
      isMoving && burst.age < shakeLength
        ? (1 - burst.age / shakeLength) ** 2 * shakeCells
        : 0;
    this.shakeX = Math.round((Math.random() * 2 - 1) * shake);
    this.shakeY = Math.round((Math.random() * 2 - 1) * shake);

    const targetX = trace.isActive ? trace.x : aura.x.value;
    const targetY = trace.isActive ? trace.y : aura.y.value;
    driveSpring(aura.x, targetX, followSpring, step, isMoving);
    driveSpring(aura.y, targetY, followSpring, step, isMoving);
    driveSpring(
      aura.strength,
      trace.isActive ? 1 : 0,
      auraSpring,
      step,
      isMoving
    );

    uniforms.uTime.value = storm.time;
    uniforms.uRain.value = this.rain;
    uniforms.uFlash.value = storm.flash;
    uniforms.uColor.value = look.print === "color" ? 1 : storm.color;
    uniforms.uStrikeSeed.value = storm.seed;
    uniforms.uLanding.value.set(storm.landing.x, storm.landing.y);
    uniforms.uAuraStrength.value = Math.max(aura.strength.value, 0) * look.aura;
    uniforms.uBurstAge.value = Number.isFinite(burst.age) ? burst.age : 10;
  }

  readonly handleBeforeRender = (renderer: WebGLRenderer) => {
    const { uniforms } = this.material;
    const viewport = readViewport(uniforms, renderer);
    const cell =
      (this.look?.cell ?? stormPrintDefaults.cell) * renderer.getPixelRatio();
    uniforms.uCell.value = cell;
    uniforms.uShake.value.set(this.shakeX * cell, this.shakeY * cell);
    uniforms.uAura.value.set(
      this.aura.x.value * viewport.z,
      this.aura.y.value * viewport.w
    );
    uniforms.uBurst.value.set(
      this.burst.x * viewport.z,
      this.burst.y * viewport.w
    );
  };

  dispose() {
    this.material.dispose();
    this.geometry.dispose();
    this.blueNoise.dispose();
  }
}

export const StormPrintScene = ({
  src,
  focus = centeredFocus,
  ink = stormPrintDefaults.ink,
  paper = stormPrintDefaults.paper,
  dither = stormPrintDefaults.dither,
  print = stormPrintDefaults.print,
  cell = stormPrintDefaults.cell,
  threshold = stormPrintDefaults.threshold,
  contrast = stormPrintDefaults.contrast,
  rain = stormPrintDefaults.rain,
  rainSpeed = stormPrintDefaults.rainSpeed,
  rainAngle = stormPrintDefaults.rainAngle,
  lightning = stormPrintDefaults.lightning,
  frequency = stormPrintDefaults.frequency,
  flash = stormPrintDefaults.flash,
  colorHold = stormPrintDefaults.colorHold,
  aura = stormPrintDefaults.aura,
  auraRadius = stormPrintDefaults.auraRadius,
  strikes = stormPrintDefaults.strikes,
  paused = stormPrintDefaults.paused,
}: StormPrintSceneProps) => {
  const invalidate = useThree((state) => state.invalidate);
  const rig = useMemo(() => new StormPrintRig(), []);
  const image = usePrintImage(src);
  const palette = useMemo(
    () => (image ? samplePalette(image.element) : null),
    [image]
  );

  useEffect(() => () => rig.dispose(), [rig]);

  useEffect(() => {
    rig.applyLook({
      aura,
      auraRadius,
      cell,
      colorHold,
      contrast,
      dither,
      flash,
      frequency,
      ink,
      lightning,
      paper,
      print,
      rain,
      rainAngle,
      rainSpeed,
      threshold,
    });
    invalidate();
  }, [
    aura,
    auraRadius,
    cell,
    colorHold,
    contrast,
    dither,
    flash,
    frequency,
    ink,
    invalidate,
    lightning,
    paper,
    print,
    rain,
    rainAngle,
    rainSpeed,
    rig,
    threshold,
  ]);

  useEffect(() => {
    rig.applyImage(image, { x: focus.x, y: focus.y });
    if (palette) {
      rig.applyPalette(palette);
    }
    invalidate();
  }, [focus.x, focus.y, image, invalidate, palette, rig]);

  const handledStrikes = useRef(strikes);
  useEffect(() => {
    if (strikes !== handledStrikes.current) {
      handledStrikes.current = strikes;
      rig.strike();
      invalidate();
    }
  }, [invalidate, rig, strikes]);

  useFrame((state, delta) => {
    rig.advance({ delta, paused, pointer: state.pointer });
  });

  return (
    <mesh
      frustumCulled={false}
      geometry={rig.geometry}
      material={rig.material}
      onBeforeRender={rig.handleBeforeRender}
      onPointerDown={(event) => {
        rig.press((event.pointer.x + 1) / 2, (event.pointer.y + 1) / 2);
        invalidate();
      }}
      raycast={hitEverywhere}
    />
  );
};

import { Color, ShaderMaterial, Vector2, Vector3 } from "three";
import type { IUniform, Texture } from "three";

import { blueNoiseSize } from "@/registry/ivan/lib/blue-noise";
import {
  createImageCoverUniforms,
  fullscreenVertexShader,
  imageCoverChunk,
} from "@/registry/ivan/lib/image-cover";
import type { ImageCoverUniforms } from "@/registry/ivan/lib/image-cover";
import {
  nearestInkChunk,
  orderedChunk,
  orderedDithers,
} from "@/registry/ivan/lib/ordered-print";
import type { OrderedDither } from "@/registry/ivan/lib/ordered-print";
import { paletteSize } from "@/registry/ivan/lib/palette";
import {
  bayerChunk,
  hashChunk,
  valueNoiseChunk,
} from "@/registry/ivan/lib/print-noise";
import {
  printSeparation,
  toneChunk,
  toneSeparationChunk,
} from "@/registry/ivan/lib/tone-curve";

export const stormDithers = [...orderedDithers, "halftone"] as const;

export type StormDither = OrderedDither | "halftone";

export const stormDitherIndex = (mode: StormDither) =>
  stormDithers.indexOf(mode);

export const stormPrintDefaults = {
  aura: 1,
  auraRadius: 1,
  cell: 3,
  colorHold: 1.2,
  contrast: 1.35,
  dither: "bayer-8",
  flash: 1,
  frequency: 0.5,
  ink: "#0B0B0C",
  lightning: true,
  paper: "#EDECE8",
  paused: false,
  print: "ink",
  rain: 1,
  rainAngle: 9,
  rainSpeed: 1,
  strikes: 0,
  threshold: 0,
} as const;

export interface StormPrintUniforms extends ImageCoverUniforms {
  uAura: IUniform<Vector2>;
  uAuraSize: IUniform<number>;
  uAuraStrength: IUniform<number>;
  uBlueNoise: IUniform<Texture | null>;
  uBurst: IUniform<Vector2>;
  uBurstAge: IUniform<number>;
  uCell: IUniform<number>;
  uColor: IUniform<number>;
  uContrast: IUniform<number>;
  uDither: IUniform<number>;
  uFlash: IUniform<number>;
  uInk: IUniform<Color>;
  uLanding: IUniform<Vector2>;
  uNoiseSize: IUniform<number>;
  uPaper: IUniform<Color>;
  uPalette: IUniform<Vector3[]>;
  uRain: IUniform<number>;
  uRainSlant: IUniform<number>;
  uRainSpeed: IUniform<number>;
  uShake: IUniform<Vector2>;
  uStrikeSeed: IUniform<number>;
  uThreshold: IUniform<number>;
  uTime: IUniform<number>;
}

const fragmentShader = `
  uniform vec3 uInk;
  uniform vec3 uPaper;
  uniform float uCell;
  uniform float uThreshold;
  uniform float uContrast;
  uniform float uTime;
  uniform float uRain;
  uniform float uRainSpeed;
  uniform float uRainSlant;
  uniform float uFlash;
  uniform float uColor;
  uniform float uStrikeSeed;
  uniform vec2 uLanding;
  uniform vec2 uShake;
  uniform vec2 uAura;
  uniform float uAuraStrength;
  uniform float uAuraSize;
  uniform vec2 uBurst;
  uniform float uBurstAge;

  const float burstLength = 0.7;
  const float dotPeriod = 3.0;
  const float colorSpread = 0.3;
  const float tileCells = 6.0;
  const float boltSegment = 0.055;

  ${imageCoverChunk}
  ${hashChunk}
  ${valueNoiseChunk}
  ${bayerChunk}
  ${orderedChunk}
  ${toneChunk}
  ${nearestInkChunk(paletteSize)}

  ${toneSeparationChunk("crispTone", printSeparation)}

  float rainAt(vec2 cell, float height) {
    float streak = 0.0;
    for (int layer = 0; layer < 3; layer++) {
      float depth = float(layer);
      float column = cell.x + floor(cell.y * uRainSlant * (1.0 + depth * 0.25));
      float seed = hash(vec2(column, depth * 17.0 + 3.0));
      float isActive = step(0.9 - depth * 0.025, seed);
      float span = 0.55 + seed * 0.6;
      float speed = (0.85 + depth * 0.35 + seed * 0.3) * uRainSpeed;
      float phase = fract((height + uTime * speed) / span + seed * 9.0);
      float streakLength = (0.06 + depth * 0.03) / span;
      float body = step(phase, streakLength) * step(0.35, 1.0 - phase / streakLength);
      streak = max(streak, body * isActive * (1.0 - depth * 0.25));
    }
    return streak;
  }

  float boltPath(vec2 point, float seed, float startX, float drift, float top, float bottom) {
    float along = (top - point.y) / boltSegment;
    float index = floor(along);
    float part = fract(along);
    float from = startX + drift * index + (hash(vec2(index, seed)) - 0.5) * 0.05;
    float to = startX + drift * (index + 1.0) + (hash(vec2(index + 1.0, seed)) - 0.5) * 0.05;
    float pathX = mix(from, to, part);
    float gap = abs(point.x - pathX) * uResolution.y / uCell;
    float inside = step(bottom, point.y) * step(point.y, top);
    return step(gap, 1.1) * inside;
  }

  float boltAt(vec2 point) {
    float seed = uStrikeSeed * 97.0;
    float top = 1.02;
    float aspect = uResolution.x / uResolution.y;
    float landX = uLanding.x * aspect;
    float steps = max((top - uLanding.y) / boltSegment, 1.0);
    float startX = landX + (hash(vec2(seed, 2.0)) - 0.5) * 0.3;
    float drift = (landX - startX) / steps;
    float trunk = boltPath(point, seed, startX, drift, top, uLanding.y);
    float forkTop = top - boltSegment * (2.0 + floor(hash(vec2(seed, 13.0)) * 3.0));
    float forkX = startX + drift * (top - forkTop) / boltSegment;
    float forkDrift = (hash(vec2(seed, 5.0)) - 0.5) * 0.06;
    float fork = boltPath(point, seed + 31.0, forkX, forkDrift, forkTop, forkTop - 0.22);
    return max(trunk, fork);
  }

  vec2 halftoneSite(vec2 pixel, float period) {
    const mat2 turn = mat2(0.7071, 0.7071, -0.7071, 0.7071);
    vec2 screen = turn * pixel / period;
    vec2 site = (floor(screen) + 0.5) * period;
    return site * turn;
  }

  float halftoneLevel(vec2 pixel, float period) {
    const mat2 turn = mat2(0.7071, 0.7071, -0.7071, 0.7071);
    vec2 offset = fract(turn * pixel / period) - 0.5;
    return clamp(1.0 - 3.1416 * dot(offset, offset), 0.0, 1.0);
  }

  void main() {
    if (uHasImage < 0.5) {
      discard;
    }
    vec2 pixel = gl_FragCoord.xy - uOrigin;
    float isHalftone = step(3.5, uDither);
    float period = uCell * dotPeriod;
    vec2 cell = floor(pixel / uCell);
    vec2 center = mix((cell + 0.5) * uCell, halftoneSite(pixel, period), isHalftone);
    vec2 stage = center / uResolution.y;

    float burstProgress = clamp(uBurstAge / burstLength, 0.0, 1.0);
    float burstLive = step(uBurstAge, burstLength) * step(0.0, uBurstAge);
    float burstRadius = (1.0 - exp2(-7.0 * burstProgress)) * 0.9;
    vec2 burstAway = stage - uBurst / uResolution.y;
    float burstDistance = length(burstAway);
    float fade = (1.0 - burstProgress) * (1.0 - burstProgress) * burstLive;
    float frontOffset = (burstDistance - burstRadius) / 0.022;
    float front = exp(-frontOffset * frontOffset) * fade;
    vec2 shimmer = burstAway / max(burstDistance, 0.001) * front * 0.012 * uResolution.y;

    vec2 uv = coverUv((center + uShake + shimmer) / uResolution);
    float lod = imageLod(mix(uCell, period * 0.7, isHalftone));

    vec3 color = textureLod(uImage, uv, lod).rgb;
    vec3 blurredColor = textureLod(uImage, uv, lod + 2.3).rgb;
    vec3 haloColor = textureLod(uImage, uv, lod + 4.2).rgb;
    float luma = dot(color, lumaWeights);
    float blurred = dot(blurredColor, lumaWeights);
    float tone = crispTone(curveTone(luma, blurred, uContrast, 1.0));
    vec3 print = curveColor(color, blurredColor, uContrast, 1.0);

    float darkness = 1.0 - smoothstep(0.12, 0.5, dot(haloColor, lumaWeights));
    float counter = mix(1.0, -1.0, smoothstep(0.35, 0.65, tone));

    float lift = 0.0;
    lift += rainAt(cell, stage.y) * uRain * darkness * 0.75;

    lift += uFlash * (0.08 + darkness * 0.5);
    lift += boltAt(center / uResolution * vec2(uResolution.x / uResolution.y, 1.0)) * step(0.12, uFlash) * counter * 2.0;

    vec2 fromAura = stage - uAura / uResolution.y;
    float above = step(0.0, fromAura.y);
    vec2 shaped = vec2(fromAura.x * 1.2, fromAura.y * mix(1.0, 0.42, above)) / max(uAuraSize, 0.001);
    float heat = exp(-dot(shaped, shaped) * 1.4) * uAuraStrength;
    float tongue = valueNoise(vec2(cell.x * 0.14, cell.y * 0.032 - uTime * 3.6));
    float flicker = valueNoise(vec2(cell.x * 0.33, cell.y * 0.09 - uTime * 7.0));
    float flame = step(1.0 - heat * 0.95, tongue * 0.78 + flicker * 0.22);
    float core = step(1.0 - heat * 0.6, tongue * 0.78 + flicker * 0.22);
    lift += flame * darkness * (0.95 + 0.4 * core);

    lift += front * counter * 1.2;

    tone += lift;
    print += lift * 0.6;

    float level = orderedLevel(cell);
    level = mix(level, halftoneLevel(pixel, period), isHalftone);

    float reach = tone - uThreshold - level;
    float halftoneEdge = max(fwidth(reach), 0.001);
    float isInk = mix(step(reach, -0.0001), 1.0 - smoothstep(-halftoneEdge, halftoneEdge, reach), isHalftone);

    vec3 mono = mix(uPaper, uInk, isInk);
    vec3 retro = toLinear(nearestInk(print - uThreshold + (level - 0.5) * colorSpread));

    vec2 tile = floor(cell / tileCells);
    vec2 tileStage = (tile + 0.5) * tileCells * uCell / uResolution.y;
    vec2 landing = uLanding * vec2(uResolution.x / uResolution.y, 1.0);
    float diagonal = length(vec2(uResolution.x / uResolution.y, 1.0));
    float order = clamp(length(tileStage - landing) / diagonal * 0.82 + hash(tile + 11.0) * 0.18, 0.0, 1.0);
    float isColor = step(order, uColor) * step(0.001, uColor);

    gl_FragColor = vec4(mix(mono, retro, isColor), 1.0);
    #include <colorspace_fragment>
  }
`;

const createUniforms = (): StormPrintUniforms => ({
  ...createImageCoverUniforms(),
  uAura: { value: new Vector2(0, 0) },
  uAuraSize: { value: 0.22 },
  uAuraStrength: { value: 0 },
  uBlueNoise: { value: null },
  uBurst: { value: new Vector2(0, 0) },
  uBurstAge: { value: 10 },
  uCell: { value: stormPrintDefaults.cell },
  uColor: { value: 0 },
  uContrast: { value: stormPrintDefaults.contrast },
  uDither: { value: stormDitherIndex(stormPrintDefaults.dither) },
  uFlash: { value: 0 },
  uInk: { value: new Color(stormPrintDefaults.ink) },
  uLanding: { value: new Vector2(0.5, 0.5) },
  uNoiseSize: { value: blueNoiseSize },
  uPalette: {
    value: Array.from({ length: paletteSize }, () => new Vector3()),
  },
  uPaper: { value: new Color(stormPrintDefaults.paper) },
  uRain: { value: stormPrintDefaults.rain },
  uRainSlant: { value: 0.16 },
  uRainSpeed: { value: stormPrintDefaults.rainSpeed },
  uShake: { value: new Vector2(0, 0) },
  uStrikeSeed: { value: 0 },
  uThreshold: { value: stormPrintDefaults.threshold },
  uTime: { value: 0 },
});

export class StormPrintMaterial extends ShaderMaterial {
  declare uniforms: StormPrintUniforms;

  constructor() {
    super({
      depthTest: false,
      depthWrite: false,
      fragmentShader,
      toneMapped: false,
      uniforms: createUniforms(),
      vertexShader: fullscreenVertexShader,
    });
  }
}

const strikeLength = 0.9;
const firstRise = 0.05;
const secondDelay = 0.2;
const secondRise = 0.04;
const secondPeak = 0.75;
const colorRise = 0.32;
const colorFade = 0.75;

const easeOutCubic = (progress: number) => 1 - (1 - progress) ** 3;
const easeInOutCubic = (progress: number) =>
  progress < 0.5 ? 4 * progress ** 3 : 1 - (-2 * progress + 2) ** 3 / 2;

export const flashEnvelope = (age: number) => {
  if (age < 0 || age > strikeLength) {
    return 0;
  }
  const first =
    age < firstRise ? age / firstRise : Math.exp(-(age - firstRise) * 14);
  const secondAge = age - secondDelay;
  let second = 0;
  if (secondAge >= 0) {
    second =
      secondAge < secondRise
        ? (secondAge / secondRise) * secondPeak
        : secondPeak * Math.exp(-(secondAge - secondRise) * 6);
  }
  return Math.min(first + second, 1);
};

export const colorEnvelope = (age: number, linger: number) => {
  if (age < 0) {
    return 0;
  }
  if (age < colorRise) {
    return easeOutCubic(age / colorRise);
  }
  const fadeAge = age - colorRise - linger;
  if (fadeAge <= 0) {
    return 1;
  }
  return 1 - easeInOutCubic(Math.min(fadeAge / colorFade, 1));
};

export const firstStrikeAt = 1.6;
export const minStrikeGap = 3;
export const manualStrikeSpacing = 1;

export const nextStrikeGap = (random: number, frequency = 0.5) => {
  const rate = Math.min(Math.max(frequency, 0), 1);
  const shortest = minStrikeGap + (1 - rate) * 6;
  return shortest + random * (3 + (1 - rate) * 4);
};

export interface StormSettings {
  lightning: boolean;
  frequency: number;
  flash: number;
  colorHold: number;
}

export interface StrikePoint {
  x: number;
  y: number;
}

export interface Storm {
  time: number;
  strikeAt: number;
  nextStrike: number;
  seed: number;
  landing: StrikePoint;
  flash: number;
  color: number;
}

export const createStorm = (): Storm => ({
  color: 0,
  flash: 0,
  landing: { x: 0.5, y: 0.5 },
  nextStrike: firstStrikeAt,
  seed: 0,
  strikeAt: -Infinity,
  time: 0,
});

export type StormMode = "running" | "still";

export interface StormStep {
  step: number;
  mode: StormMode;
  isRequested: boolean;
  landing?: StrikePoint | null;
  random: () => number;
}

const skyLanding = (random: () => number): StrikePoint => ({
  x: 0.12 + random() * 0.76,
  y: 0.36 + random() * 0.2,
});

const strike = (
  storm: Storm,
  settings: StormSettings,
  random: () => number,
  landing: StrikePoint
) => {
  storm.strikeAt = storm.time;
  storm.seed = random();
  storm.landing = { x: landing.x, y: landing.y };
  storm.nextStrike = storm.time + nextStrikeGap(random(), settings.frequency);
};

export const advanceStorm = (
  storm: Storm,
  settings: StormSettings,
  { step, mode, isRequested, landing = null, random }: StormStep
) => {
  if (mode === "still") {
    storm.flash = 0;
    storm.color = 0;
    return storm;
  }
  storm.time += step;
  const canStrike = storm.time - storm.strikeAt >= manualStrikeSpacing;
  if (isRequested && canStrike) {
    strike(storm, settings, random, landing ?? skyLanding(random));
  } else if (settings.lightning && storm.time >= storm.nextStrike) {
    strike(storm, settings, random, skyLanding(random));
  }
  const age = storm.time - storm.strikeAt;
  storm.flash = flashEnvelope(age) * Math.min(Math.max(settings.flash, 0), 1);
  storm.color = colorEnvelope(age, settings.colorHold);
  return storm;
};

